//! Lists hand-written strict certificates in source, so a test can pin the set.
//!
//! Code generated by `#[fip(strict = true)]` and `fip_fn!` never appears in source,
//! so anything found here was written by hand:
//!
//! - `Cert::assume` (a hand-made `fip_strict::Cert`);
//! - `unsafe impl` of `FipBound` (a hand-made value certificate);
//! - any identifier starting with `__fip_strict_` (a certificate defined or
//!   re-exported by hand, including `use a::__fip_strict_g as __fip_strict_f;`).

use std::fs;
use std::path::{Path, PathBuf};

/// One occurrence: file, 1-based line, trimmed line text.
pub type Occurrence = (PathBuf, usize, String);

/// Every line under `dir` (`.rs` files, recursively) that contains a hand-written
/// certificate, outside `//` comments.
///
/// # Panics
///
/// Panics if `dir` or a file in it cannot be read.
#[must_use]
pub fn hand_written(dir: &Path) -> Vec<Occurrence> {
    let mut files = Vec::new();
    collect(dir, &mut files);
    files.sort();
    let mut out = Vec::new();
    for f in files {
        let text = fs::read_to_string(&f).expect("read source file");
        for (n, line) in text.lines().enumerate() {
            let code = line.split("//").next().unwrap_or("");
            let hit = code.contains("Cert::assume")
                || (code.contains("unsafe impl") && code.contains("FipBound"))
                || code.contains("__fip_strict_");
            if hit {
                out.push((f.clone(), n + 1, line.trim().to_string()));
            }
        }
    }
    out
}

fn collect(dir: &Path, out: &mut Vec<PathBuf>) {
    for e in fs::read_dir(dir).expect("read source dir") {
        let p = e.expect("dir entry").path();
        if p.is_dir() {
            collect(&p, out);
        } else if p.extension().is_some_and(|x| x == "rs") {
            out.push(p);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn finds_each_form_and_ignores_comments() {
        let dir = std::env::temp_dir().join(format!("fip-certs-{}", std::process::id()));
        fs::create_dir_all(&dir).expect("mkdir");
        fs::write(
            dir.join("a.rs"),
            "// Cert::assume in a comment\n\
             pub const __fip_strict_f: fip_strict::Cert = unsafe { fip_strict::Cert::assume(0) };\n\
             unsafe impl fip_strict::FipBound for W { const ALLOCS: u64 = 0; }\n\
             pub use m::__fip_strict_g as __fip_strict_h;\n\
             fn clean() {}\n",
        )
        .expect("write");
        let found = hand_written(&dir);
        fs::remove_dir_all(&dir).expect("cleanup");
        let lines: Vec<usize> = found.iter().map(|o| o.1).collect();
        assert_eq!(lines, vec![2, 3, 4]);
    }
}
